{  "explanation": "Place four identical right triangles (legs a, b, hypotenuse c) inside a square of side a+b. In the first arrangement, the uncovered region is a tilted square of side c, so its area is c². Slide the same four triangles into the corners and the uncovered region becomes two squares of areas a² and b². Since the outer square and the four triangles are unchanged, the uncovered areas must be equal: a² + b² = c². Use the 'Rearrange' slider to morph between the two configurations, and change legs a and b to see the proof hold for any right triangle.",
  "manimCode": "// ---- Pythagorean theorem: proof by rearrangement ----
const cx = -1.2, cy = 0.1;
let a = 2, b = 1, t = 0;

function lerp(u, v, k) { return u + (v - u) * k; }
function lerpP(p, q, k) { return [lerp(p[0], q[0], k), lerp(p[1], q[1], k), 0]; }

// Key points of the construction for current a, b
function geom() {
  const s = (a + b) / 2;
  return {
    s: s,
    BL: [cx - s, cy - s, 0], BR: [cx + s, cy - s, 0],
    TR: [cx + s, cy + s, 0], TL: [cx - s, cy + s, 0],
    P1: [cx - s + a, cy - s, 0], P2: [cx + s, cy - s + a, 0],
    P3: [cx + s - a, cy + s, 0], P4: [cx - s, cy + s - a, 0],
    Q:  [cx - s + a, cy + s - a, 0],
    Ta: [cx - s + a, cy + s, 0], Rb: [cx + s, cy + s - a, 0]
  };
}

const g0 = geom();

const outerSquare = new Polygon({ vertices: [g0.BL, g0.BR, g0.TR, g0.TL], color: WHITE });
outerSquare.setStrokeWidth(3).setFillOpacity(0);

function makeTri(col) {
  const tri = new Polygon({ vertices: [g0.BL, g0.BR, g0.TR], color: WHITE });
  tri.setFill(col, 0.8).setStrokeWidth(2);
  return tri;
}
const tri1 = makeTri(BLUE);
const tri2 = makeTri(GREEN);
const tri3 = makeTri(ORANGE);
const tri4 = makeTri(PURPLE);

// Highlight regions
const cSquare = new Polygon({ vertices: [g0.P1, g0.P2, g0.P3, g0.P4], color: YELLOW });
cSquare.setFill(YELLOW, 0.4).setStrokeWidth(3);
const aSquare = new Polygon({ vertices: [g0.TL, g0.Ta, g0.Q, g0.P4], color: GOLD });
aSquare.setFill(GOLD, 0).setStrokeWidth(0.01);
const bSquare = new Polygon({ vertices: [g0.P1, g0.BR, g0.Rb, g0.Q], color: TEAL });
bSquare.setFill(TEAL, 0).setStrokeWidth(0.01);

// Divider lines for arrangement 2 (2-vertex polygons act as line segments)
const divV = new Polygon({ vertices: [g0.P1, g0.Ta], color: WHITE });
divV.setStrokeWidth(0.01).setFillOpacity(0);
const divH = new Polygon({ vertices: [g0.P4, g0.Rb], color: WHITE });
divH.setStrokeWidth(0.01).setFillOpacity(0);

// Labels
const cLab = new MathTex({ latex: 'c^2' }); await cLab.waitForRender();
cLab.setColor(YELLOW); cLab.scale(1.1);
const aLab = new MathTex({ latex: 'a^2' }); await aLab.waitForRender();
aLab.setColor(GOLD); aLab.scale(1.1);
const bLab = new MathTex({ latex: 'b^2' }); await bLab.waitForRender();
bLab.setColor(TEAL); bLab.scale(1.1);
const legA = new MathTex({ latex: 'a' }); await legA.waitForRender(); legA.scale(0.8);
const legB = new MathTex({ latex: 'b' }); await legB.waitForRender(); legB.scale(0.8);
const legC = new MathTex({ latex: 'c' }); await legC.waitForRender(); legC.scale(0.8);

function setTri(tri, A, B, k) {
  tri.setVertices([lerpP(A[0], B[0], k), lerpP(A[1], B[1], k), lerpP(A[2], B[2], k)]);
}

// Master update: u = 0 -> hypotenuse-square arrangement, u = 1 -> two-squares arrangement
function updateAll(u) {
  t = u;
  const g = geom();
  outerSquare.setVertices([g.BL, g.BR, g.TR, g.TL]);
  setTri(tri1, [g.P1, g.BR, g.P2], [g.P1, g.Q, g.P4], u);
  setTri(tri2, [g.P2, g.TR, g.P3], [g.Rb, g.TR, g.Ta], u);
  setTri(tri3, [g.P3, g.TL, g.P4], [g.Ta, g.Q, g.Rb], u);
  setTri(tri4, [g.P4, g.BL, g.P1], [g.P4, g.BL, g.P1], u);
  cSquare.setVertices([g.P1, g.P2, g.P3, g.P4]);
  aSquare.setVertices([g.TL, g.Ta, g.Q, g.P4]);
  bSquare.setVertices([g.P1, g.BR, g.Rb, g.Q]);
  divV.setVertices([g.P1, g.Ta]);
  divH.setVertices([g.P4, g.Rb]);

  const out = Math.max(0, 1 - 1.6 * u);
  const inn = Math.max(0, Math.min(1, (u - 0.4) / 0.6));
  cSquare.setFillOpacity(0.4 * out);
  cSquare.setStrokeWidth(3 * out + 0.01);
  aSquare.setFillOpacity(0.45 * inn);
  aSquare.setStrokeWidth(3 * inn + 0.01);
  bSquare.setFillOpacity(0.45 * inn);
  bSquare.setStrokeWidth(3 * inn + 0.01);
  divV.setStrokeWidth(2.5 * inn + 0.01);
  divH.setStrokeWidth(2.5 * inn + 0.01);

  cLab.setOpacity(out); cLab.moveTo([cx, cy, 0]);
  aLab.setOpacity(inn); aLab.moveTo([cx - g.s + a / 2, cy + g.s - a / 2, 0]);
  bLab.setOpacity(inn); bLab.moveTo([cx + g.s - b / 2, cy - g.s + b / 2, 0]);
  legA.setOpacity(out); legA.moveTo([cx + g.s + 0.35, cy - g.s + a / 2, 0]);
  legB.setOpacity(out); legB.moveTo([cx - g.s + a + b / 2, cy - g.s - 0.35, 0]);
  const mx = (g.P1[0] + g.P2[0]) / 2, my = (g.P1[1] + g.P2[1]) / 2;
  const dx = cx - mx, dy = cy - my;
  const len = Math.hypot(dx, dy) || 1;
  legC.setOpacity(out); legC.moveTo([mx + 0.4 * dx / len, my + 0.4 * dy / len, 0]);
}

// Numeric readout (Text is immutable: remove + recreate)
let readout = null;
function updateReadout() {
  if (readout) scene.remove(readout);
  const sum = (a * a + b * b).toFixed(2);
  readout = new Text({ text: 'a^2 + b^2 = ' + sum + ' = c^2', color: WHITE, fontSize: 24 });
  readout.moveTo([3.1, -3.15, 0]);
  scene.add(readout);
}

// ---------- Intro animation ----------
const title = new Text({ text: 'Pythagorean Theorem: Proof by Rearrangement', color: WHITE, fontSize: 30 });
title.moveTo([-1.2, 3.4, 0]);
await scene.play(new Write(title));

updateAll(0);
scene.add(outerSquare, aSquare, bSquare, cSquare, divV, divH, tri1, tri2, tri3, tri4);
await scene.play(new Create(outerSquare));
await scene.play(new AnimationGroup([
  new DrawBorderThenFill(tri1),
  new DrawBorderThenFill(tri2),
  new DrawBorderThenFill(tri3),
  new DrawBorderThenFill(tri4)
]));
scene.add(cLab, aLab, bLab, legA, legB, legC);
await scene.play(new AnimationGroup([
  new FadeIn(cLab), new FadeIn(legA), new FadeIn(legB), new FadeIn(legC)
]));
await scene.wait(1);

// The rearrangement: four triangles slide, c^2 region becomes a^2 + b^2
const steps = 50;
for (let k = 1; k <= steps; k++) {
  updateAll(k / steps);
  await scene.wait(0.03);
}
await scene.wait(0.5);

const eq = new MathTex({ latex: 'a^2 + b^2 = c^2' });
await eq.waitForRender();
eq.scale(1.4);
eq.moveTo([-1.2, -3.15, 0]);
await scene.play(new Write(eq));
updateReadout();
await scene.play(new FadeIn(readout));

// ---------- Interactivity ----------
let animating = false;
const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Rearrange', min: 0, max: 1, value: 1, step: 0.01, onChange: (v) => {
  if (!animating) updateAll(v);
}});
controls.addSlider({ label: 'Leg a', min: 1.2, max: 2.6, value: 2, step: 0.05, onChange: (v) => {
  a = v; updateAll(t); updateReadout();
}});
controls.addSlider({ label: 'Leg b', min: 0.8, max: 2.0, value: 1, step: 0.05, onChange: (v) => {
  b = v; updateAll(t); updateReadout();
}});
controls.addButton({ label: 'Replay morph', onClick: async () => {
  if (animating) return;
  animating = true;
  updateAll(0);
  for (let k = 1; k <= 50; k++) { updateAll(k / 50); await scene.wait(0.03); }
  animating = false;
}});

await scene.wait(999999);"}

